def unique_paths_with_obstacles(g):
    C = len(g[0]); dp = [0] * C; dp[0] = 1
    for row in g:
        for j in range(C):
            if row[j]: dp[j] = 0
            elif j: dp[j] += dp[j - 1]
    return dp[-1]

