long long uniquePathsWithObstacles(vector<vector<int>>& g) {
    int C = g[0].size(); vector<long long> dp(C, 0); dp[0] = 1;
    for (auto& row : g) for (int j = 0; j < C; j++) { if (row[j]) dp[j] = 0; else if (j) dp[j] += dp[j - 1]; }
    return dp[C - 1];
}
